<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref, toRaw } from 'vue'
import { request, errorText } from '../src/api'
import { useAuth } from '../src/stores/auth'
import type { Product, Article, Order } from '../src/types'
import { money, orderStatusNames } from '../src/types'
import RetailHistory from '../src/components/RetailHistory.vue'
type RecordProduct = { product: Product; status: string; revision: number; articleIds: string[] }
type Review = { id: string; productId: string; author: string; rating: number; content: string; reply: string; createdAt: string }
type AdminOrder = { order: Order; fulfillmentStatus: string; carrier: string; trackingNumber: string }
type Summary = { products: number; activeProducts: number; stock: number; reviewCount: number; orders: number; paidTotal: number; lowStock: { id: string; name: string; color: string; size_label: string; stock: number }[] }
const access = ref<{ admin: boolean; setupRequired: boolean }>(), setupToken = ref(''), busy = ref(false), error = ref(''), success = ref('')
const auth=useAuth(),loginName=ref(''),loginPassword=ref('')
const tab = ref('products'), filter = ref(''), dynasty = ref(''), records = ref<RecordProduct[]>([]), articles = ref<Article[]>([]), reviews = ref<Review[]>([]), orders = ref<AdminOrder[]>([]), summary = ref<Summary>(), audit = ref<Record<string, string>[]>([])
const editing = ref<RecordProduct>(), creating = ref(false), articleEditing = ref<Article>(), keywordText = ref(''), tagText = ref(''), sceneText = ref(''), accessoryText = ref('')
const deleting = ref<RecordProduct>(), deleteDialog = ref<HTMLDialogElement>()
const tickets = ref<{id:string;number:string;category:string;message:string;status:string;reply:string;createdAt:string}[]>([])
const shipment = reactive<Record<string, { carrier: string; trackingNumber: string }>>({})
const customers=ref<{id:string;username:string;displayName:string;role:string;createdAt:string;orderCount:number}[]>([])
const productStatus = ref('ACTIVE')
const matchingRecords = computed(() => records.value.filter(r => (!dynasty.value || r.product.dynasty === dynasty.value) && (!filter.value || `${r.product.id} ${r.product.name} ${r.product.form}`.includes(filter.value.trim()))))
const shown = computed(() => matchingRecords.value.filter(r => !productStatus.value || r.status === productStatus.value))
const visibilityFilters = computed(() => [
  { value: 'ACTIVE', label: '前台展示', count: matchingRecords.value.filter(r => r.status === 'ACTIVE').length },
  { value: 'DRAFT', label: '草稿', count: matchingRecords.value.filter(r => r.status === 'DRAFT').length },
  { value: 'ARCHIVED', label: '已下架', count: matchingRecords.value.filter(r => r.status === 'ARCHIVED').length },
  { value: '', label: '全部记录', count: matchingRecords.value.length }
])
const tabs = [{ id: 'retail', label: 'AI 接待与待办' }, { id: 'products', label: '商品与库存' }, { id: 'customers', label: '注册用户' }, { id: 'knowledge', label: '衣冠史料' }, { id: 'reviews', label: '评论回复' }, { id: 'orders', label: '订单与发货' }, { id: 'support', label: '客服留言' }, { id: 'audit', label: '操作记录' }]
const statusNames: Record<string,string> = { ACTIVE:'已上架',DRAFT:'草稿',ARCHIVED:'已下架' }
const split = (s: string) => s.split(/[,，]/).map(v => v.trim()).filter(Boolean)
async function run(fn: () => Promise<void>) { if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn()}catch(e){error.value=errorText(e)}finally{busy.value=false} }
async function loadData() {
  const [p,a,r,o,s,l,t,u] = await Promise.all([
    request<RecordProduct[]>('GET','/admin/products'),request<Article[]>('GET','/admin/articles'),request<Review[]>('GET','/admin/reviews'),request<AdminOrder[]>('GET','/admin/orders'),request<Summary>('GET','/admin/summary'),request<Record<string,string>[]>('GET','/admin/audit'),request<typeof tickets.value>('GET','/admin/support'),request<typeof customers.value>('GET','/admin/customers')
  ]);records.value=p;articles.value=a;reviews.value=r;orders.value=o;summary.value=s;audit.value=l;tickets.value=t;customers.value=u
  for(const entry of o) shipment[entry.order.id]={carrier:entry.carrier,trackingNumber:entry.trackingNumber}
}
async function initialize(){await auth.initialize();if(!auth.authenticated){access.value=undefined;return}access.value=await request('GET','/admin/access');if(access.value?.admin)await loadData()}
async function login(){await auth.submit('login',loginName.value,loginPassword.value,'');loginPassword.value='';await initialize()}
function edit(r: RecordProduct) {editing.value=structuredClone(toRaw(r));creating.value=false;tagText.value=r.product.tags.join('，');sceneText.value=r.product.scenes.join('，');accessoryText.value=r.product.accessoryIds.join('，');success.value=''}
function newProduct(){
  const id=`p_${Date.now()}`;creating.value=true;tagText.value='';sceneText.value='shuyuan';accessoryText.value=''
  editing.value={status:'DRAFT',revision:0,articleIds:[],product:{id,name:'',dynasty:'明',category:'女装',form:'',description:'',scenes:[],tags:[],colors:['月白'],images:[],accessoryIds:[],sizeChart:structuredClone(toRaw(records.value[0]?.product.sizeChart || [])),skus:['S','M','L','XL'].map(size=>({id:`${id}-${size}`,color:'月白',size,stock:0,price:199}))}}
}
async function requestDelete(record: RecordProduct) {
  if (busy.value || !canDelete(record)) return
  deleting.value=structuredClone(toRaw(record));error.value='';success.value=''
  await nextTick()
  if (!deleteDialog.value?.open) deleteDialog.value?.showModal()
}
function cancelDelete() {
  if (busy.value) return
  deleteDialog.value?.close();deleting.value=undefined
}
function canDelete(record: RecordProduct) {
  return ['DRAFT','ARCHIVED'].includes(productStatus.value) && record.status===productStatus.value
}
async function deleteProduct() {
  if (!deleting.value) return
  const record=deleting.value
  if (!['DRAFT','ARCHIVED'].includes(record.status)) throw new Error('只能删除草稿或已下架商品，请先下架再删除。')
  await request('DELETE',`/admin/products/${encodeURIComponent(record.product.id)}`,undefined,undefined,{revision:record.revision})
  records.value=records.value.filter(item=>item.product.id!==record.product.id)
  deleteDialog.value?.close();deleting.value=undefined
  if (editing.value?.product.id===record.product.id) editing.value=undefined
  await loadData()
}
function addSku(){const p=editing.value?.product;if(p)p.skus.push({id:`${p.id}-${Date.now()}`,color:'',size:'',stock:0,price:199})}
async function saveProduct(){if(!editing.value)return;const value=editing.value;value.product.tags=split(tagText.value);value.product.scenes=split(sceneText.value);value.product.accessoryIds=split(accessoryText.value);value.product.colors=[...new Set(value.product.skus.map(s=>s.color))];await request(creating.value?'POST':'PUT',creating.value?'/admin/products':`/admin/products/${value.product.id}`,undefined,value);editing.value=undefined;await loadData();productStatus.value=value.status}
async function upload(event: Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!editing.value)return;await run(async()=>{const body=new FormData();body.append('file',file);const data=await request<{url:string}>('POST','/admin/media',undefined,body);if(editing.value)editing.value.product.images=[data.url];success.value='图片已上传，保存商品后生效。'})}
function editArticle(a?: Article){articleEditing.value=a?structuredClone(toRaw(a)):{id:`a_${Date.now()}`,title:'',topic:'服饰史料',content:'',kind:'FACT',source:'',keywords:[],claimKey:`claim_${Date.now()}`,claimValue:'',};keywordText.value=a?.keywords.join('，')||''}
async function saveArticle(){if(!articleEditing.value)return;articleEditing.value.keywords=split(keywordText.value);await request('PUT',`/admin/articles/${articleEditing.value.id}`,undefined,articleEditing.value);articleEditing.value=undefined;await loadData();success.value='史料已保存，可在商品编辑中关联。'}
async function confirmReply(r: Review){const reply=r.reply.trim();if(!reply)throw new Error('请填写商家回复。');await request('PUT',`/admin/reviews/${r.id}`,undefined,{reply});await loadData();success.value='商家回复已确认并保存。'}
onMounted(()=>run(initialize))
</script>

<template>
  <div class="page admin-page">
    <header class="section-heading"><div><p class="eyebrow">汉韵镜 · 商家后台</p><h1>掌好一间衣冠小馆</h1><p class="muted">商品、库存与每一条反馈，在这里有序管理。</p></div><div class="actions"><a class="button" href="http://127.0.0.1:5173/culture" target="_blank" rel="noopener">查看前台 ↗</a><button :disabled="busy" @click="run(initialize)">刷新</button></div></header>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" class="notice" role="status">{{ success }}</p><p v-if="busy" role="status">正在处理…</p>
    <section v-if="!auth.authenticated" class="admin-welcome"><div class="admin-welcome-copy"><span class="brand-seal">掌</span><h2>一间小馆，井井有条</h2><p>从一件新衣的上架，到一位衣友的留言，<br>在这里打理你的汉韵镜。</p><div class="welcome-features"><span>商品与库存</span><span>价格与款式</span><span>订单与用户</span><span>评论与客服</span></div></div><form class="panel admin-login" @submit.prevent="run(login)"><p class="eyebrow">商家工作台</p><h2>管理员登录</h2><label>管理账号<input v-model="loginName" autocomplete="username" required maxlength="32" placeholder="输入管理员用户名"></label><label>密码<input v-model="loginPassword" type="password" autocomplete="current-password" required maxlength="72" placeholder="输入管理员密码"></label><button class="primary full" :disabled="busy">{{ busy?'正在登录…':'进入管理后台 →' }}</button><p class="caption">使用已授权的管理账号登录。</p></form></section>
    <section v-if="access?.setupRequired" class="panel setup-panel"><h2>初始化管理员</h2><p>先登录你要用作管理员的账号，再输入服务器本地 <code>.local/admin-setup-token.txt</code> 中的一次性口令。</p><form @submit.prevent="run(async()=>{await request('POST','/admin/setup',undefined,{token:setupToken});setupToken='';await initialize()})"><label>初始化口令<input v-model="setupToken" type="password" required autocomplete="off"></label><button class="primary" :disabled="busy">将当前账号设为管理员</button></form></section>
    <div v-else-if="access && !access.admin" class="notice">当前账号没有管理权限，请使用管理员账号登录。<button :disabled="busy" @click="run(async()=>{await auth.logout();access=undefined})">切换管理员账号</button></div>
    <template v-if="access?.admin">
      <div v-if="summary" class="metrics"><article class="panel"><span>在售 / 全部商品</span><strong>{{ summary.activeProducts }}<small> / {{ summary.products }}</small></strong></article><article class="panel"><span>规格总库存</span><strong>{{ summary.stock }}</strong></article><article class="panel"><span>评论总数</span><strong>{{ summary.reviewCount }}</strong></article><article class="panel"><span>{{ summary.orders }} 笔订单 · 已模拟支付</span><strong class="amount">{{ money(summary.paidTotal) }}</strong></article></div>
      <nav class="admin-tabs" aria-label="后台模块"><button v-for="item in tabs" :key="item.id" :class="{selected:tab===item.id}" :aria-pressed="tab===item.id" @click="tab=item.id">{{ item.label }}</button></nav>
      <RetailHistory v-if="tab==='retail'" admin/>
      <section v-if="tab==='customers'" class="panel table-scroll"><h2>注册用户</h2><p class="caption">最新 500 个注册账号，密码以加盐哈希保存，后台不显示密码。</p><table><thead><tr><th>用户名</th><th>昵称</th><th>角色</th><th>注册时间</th><th>订单数</th></tr></thead><tbody><tr v-for="u in customers" :key="u.id"><td>{{ u.username }}</td><td>{{ u.displayName }}</td><td>{{ u.role==='ADMIN'?'管理员':'用户' }}</td><td>{{ new Date(u.createdAt).toLocaleString('zh-CN') }}</td><td>{{ u.orderCount }}</td></tr></tbody></table></section>
      <section v-if="tab==='products'">
        <div class="admin-toolbar"><input v-model="filter" placeholder="搜索商品名称、编号或款式" aria-label="搜索商品"><select v-model="dynasty" aria-label="筛选朝代"><option value="">全部朝代</option><option v-for="d in ['汉','唐','宋','元','明']" :key="d">{{ d }}</option></select><button class="primary" @click="newProduct">＋ 添加衣服款式</button></div>
        <div class="visibility-filters" role="group" aria-label="商品展示状态"><button v-for="option in visibilityFilters" :key="option.value" :class="{selected:productStatus===option.value}" :aria-pressed="productStatus===option.value" @click="productStatus=option.value">{{ option.label }} <span>{{ option.count }}</span></button></div>
        <p class="caption">“前台展示”与商城在售目录一致，按朝代完整展示。草稿和已下架商品仅在后台保留，需保存为“已上架”后才对游客展示。</p>
        <p v-if="summary?.lowStock.length" class="notice">{{ summary.lowStock.length }} 个在售规格库存低于 5 件，请及时补充。</p>
        <div class="table-scroll panel"><table><thead><tr><th>衣裳</th><th>朝代 / 款式</th><th>价格</th><th>库存</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in shown" :key="r.product.id" :data-product-id="r.product.id"><td><div class="catalogue-cell"><img v-if="r.product.images[0]" :src="r.product.images[0]" alt=""><div>{{ r.product.name }}<small>{{ r.product.id }} · {{ r.product.skus.length }} 个规格</small></div></div></td><td>{{ r.product.dynasty }} · {{ r.product.form }}</td><td>{{ r.product.skus.length ? money(Math.min(...r.product.skus.map(s=>s.price))) + ' 起' : '暂无规格' }}</td><td>{{ r.product.skus.reduce((sum,s)=>sum+s.stock,0) }}</td><td><span class="tag">{{ statusNames[r.status] }}</span><small class="visibility-note">{{ r.status==='ACTIVE'?'游客可见':'仅后台可见' }}</small></td><td><div class="catalogue-actions"><button @click="edit(r)">编辑</button><a v-if="r.status==='ACTIVE'" :href="'http://127.0.0.1:5173/product/' + r.product.id" target="_blank" rel="noopener">查看前台 ↗</a><button v-if="canDelete(r)" type="button" class="delete-product" :disabled="busy" :aria-label="'删除' + r.product.name" @click="requestDelete(r)">删除</button></div></td></tr></tbody></table><p v-if="!shown.length" class="state">暂无匹配商品</p></div>
      </section>
      <section v-if="tab==='knowledge'" class="panel"><div class="between"><h2>衣冠史料库</h2><button class="primary" @click="editArticle()">＋ 添加史料</button></div><p class="caption">每条史实请注明可核查的文献或博物馆出处。</p><details v-for="a in articles" :key="a.id"><summary>{{ a.title }} <span class="tag">{{ '史实' }}</span></summary><p>{{ a.content }}</p><p class="caption">{{ a.source }}</p><button @click="editArticle(a)">编辑史料</button></details></section>
      <section v-if="tab==='reviews'"><p class="caption">最新 200 条评论</p><article v-for="r in reviews" :key="r.id" class="panel review-panel"><div class="between"><strong>{{ r.author }} · {{ r.rating }} 星</strong></div><p class="caption">{{ records.find(p=>p.product.id===r.productId)?.product.name || r.productId }} · {{ new Date(r.createdAt).toLocaleString('zh-CN') }}</p><p>{{ r.content }}</p><label>商家回复<textarea v-model="r.reply" rows="2" maxlength="2000"/></label><div class="actions"><button class="primary" :disabled="busy || !r.reply.trim()" @click="run(()=>confirmReply(r))">确认回复</button></div></article><p v-if="!reviews.length" class="state">还没有评论</p></section>
      <section v-if="tab==='orders'"><p class="caption">最新 200 笔订单。现有支付流程为模拟支付，登记物流不会创建真实快递订单。</p><article v-for="entry in orders" :key="entry.order.id" class="panel review-panel"><div class="between"><strong>{{ entry.order.orderNumber }}</strong><span class="tag">{{ orderStatusNames[entry.order.status] }} · {{ entry.fulfillmentStatus==='SHIPPED'?'已登记发货':'未发货' }}</span></div><p>{{ entry.order.recipient }} · {{ entry.order.phone }} · {{ entry.order.region }} {{ entry.order.address }}</p><p v-for="line in entry.order.cart.lines" :key="line.id">{{ line.productName }} / {{ line.color }} / {{ line.size }} × {{ line.quantity }} · {{ money(line.subtotal) }}</p><strong>合计 {{ money(entry.order.cart.total) }}</strong><form v-if="entry.order.status==='DEMO_PAID' && entry.fulfillmentStatus==='UNSHIPPED' && shipment[entry.order.id]" class="shipping-form" @submit.prevent="run(async()=>{await request('POST',`/admin/orders/${entry.order.id}/ship`,undefined,shipment[entry.order.id]);await loadData();success='已登记发货'})"><label>物流公司<input v-model="shipment[entry.order.id]!.carrier" required maxlength="80"></label><label>物流单号<input v-model="shipment[entry.order.id]!.trackingNumber" required maxlength="100"></label><button class="primary" :disabled="busy">登记发货</button></form><p v-if="entry.fulfillmentStatus==='SHIPPED'">{{ entry.carrier }} · {{ entry.trackingNumber }}</p></article><p v-if="!orders.length" class="state">暂无订单</p></section>
      <section v-if="tab==='support'"><article v-for="ticket in tickets" :key="ticket.id" class="panel review-panel"><strong>{{ ticket.number }} · {{ ticket.category }}</strong><p>{{ ticket.message }}</p><label>客服回复<textarea v-model="ticket.reply" rows="3" maxlength="2000"/></label><button class="primary" :disabled="busy" @click="run(async()=>{await request('PUT',`/admin/support/${ticket.id}`,undefined,{reply:ticket.reply});await loadData();success='回复已保存，用户可在客服留言记录查看'})">保存回复</button></article><p v-if="!tickets.length" class="state">暂无客服留言</p></section>
      <section v-if="tab==='audit'" class="panel table-scroll"><table><thead><tr><th>时间</th><th>操作</th><th>对象</th><th>说明</th></tr></thead><tbody><tr v-for="(row,i) in audit" :key="i"><td>{{ new Date(row.created_at || '').toLocaleString('zh-CN') }}</td><td>{{ row.action }}</td><td>{{ row.target_id }}</td><td>{{ row.summary }}</td></tr></tbody></table><p v-if="!audit.length" class="state">暂无管理操作</p></section>
    </template>
    <dialog ref="deleteDialog" class="delete-dialog" aria-labelledby="delete-product-title" aria-describedby="delete-product-description" @cancel.prevent="cancelDelete" @click="event => { if (event.target === deleteDialog) cancelDelete() }">
      <h2 id="delete-product-title">确认删除这件衣裳？</h2>
      <p class="delete-product-name">{{ deleting?.product.name }}</p>
      <p id="delete-product-description">删除后，该商品将从前台和后台商品列表中移除。已有订单与咨询记录会保留。</p>
      <p v-if="error" class="error" role="alert">{{ error }}</p>
      <div class="actions"><button type="button" autofocus :disabled="busy" @click="cancelDelete">取消</button><button type="button" class="delete-confirm" :disabled="busy || !deleting" @click="run(deleteProduct)">{{ busy?'正在删除…':'确认删除' }}</button></div>
    </dialog>
    <div v-if="editing" class="editor-overlay" @click.self="editing=undefined"><section class="editor panel" role="dialog" aria-modal="true" aria-labelledby="product-editor-title"><div class="between"><h2 id="product-editor-title">{{ creating?'添加衣服款式':'编辑衣裳' }}</h2><button aria-label="关闭编辑" @click="editing=undefined">×</button></div><form @submit.prevent="run(saveProduct)"><div class="form-grid"><label>商品名称<input v-model="editing.product.name" required maxlength="120"></label><label>上架状态<select v-model="editing.status"><option value="DRAFT">草稿</option><option value="ACTIVE">已上架</option><option value="ARCHIVED">已下架</option></select></label><label>朝代<select v-model="editing.product.dynasty"><option v-for="d in ['汉','唐','宋','元','明']" :key="d">{{ d }}</option></select></label><label>衣服款式<input v-model="editing.product.form" required maxlength="80"></label><label>分类<select v-model="editing.product.category"><option>女装</option><option>男装</option><option>中性</option><option>配饰</option><option>上衣</option></select></label><label>风格标签（逗号分隔）<input v-model="tagText"></label><label>适用场景编号（逗号分隔）<input v-model="sceneText"></label><label>搭配商品编号（逗号分隔）<input v-model="accessoryText"></label></div><label>商品说明<textarea v-model="editing.product.description" required rows="3" maxlength="6000"/></label><div class="image-editor"><img v-if="editing.product.images[0]" :src="editing.product.images[0]" alt="商品图预览"><label>商品图（PNG/JPEG，最大5MB，512至4096像素）<input type="file" accept="image/png,image/jpeg" :disabled="busy" @change="upload"></label></div><h3>价格与库存</h3><div class="table-scroll"><table><thead><tr><th>颜色</th><th>尺码</th><th>单价（元）</th><th>库存（件）</th></tr></thead><tbody><tr v-for="s in editing.product.skus" :key="s.id"><td><input v-model="s.color" required maxlength="40" aria-label="颜色"></td><td><input v-model="s.size" required maxlength="20" aria-label="尺码"></td><td><input v-model.number="s.price" type="number" min="0.01" max="999999.99" step="0.01" required aria-label="价格"></td><td><input v-m